@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize(Roles = "Dispatcher")]
@inject ShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>📋 Dispatcher Dashboard</h2>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="filterStatus">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-success" @onclick="ShowCreateForm">+ New Shipment</button>
        <button class="btn btn-outline-secondary ms-2" @onclick="LoadShipments">Refresh</button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5>Create New Shipment</h5>
            <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="createShipment">
                <div class="row g-2">
                    <div class="col-md-3">
                        <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" required />
                    </div>
                    <div class="col-md-3">
                        <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" required />
                    </div>
                    <div class="col-md-3">
                        <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" required />
                    </div>
                    <div class="col-md-3">
                        <input class="form-control" placeholder="Description" @bind="newShipment.Description" required />
                    </div>
                    <div class="col-md-3">
                        <label class="form-label">Est. Delivery</label>
                        <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                    </div>
                    <div class="col-md-3 d-flex align-items-end">
                        <button type="submit" class="btn btn-primary me-2">Create</button>
                        <button type="button" class="btn btn-secondary" @onclick="() => showCreateForm = false">Cancel</button>
                    </div>
                </div>
            </EditForm>
        </div>
    </div>
}

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments is null || shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Customer</th>
                    <th>Shipped</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><code>@shipment.TrackingNumber</code></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.CustomerEmail</td>
                        <td>@shipment.ShippedDate.ToString("MMM dd, yyyy")</td>
                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                    value="@shipment.Status"
                                    @onchange="(e) => UpdateStatus(shipment, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status" selected="@(shipment.Status == status)">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<ShipmentDto>? shipments;
    private bool loading = true;
    private string filterText = "";
    private string filterStatus = "";
    private bool showCreateForm;
    private NewShipmentModel newShipment = new();

    private IEnumerable<ShipmentDto> FilteredShipments => shipments?
        .Where(s => string.IsNullOrEmpty(filterText) ||
                    s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                    s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase))
        .Where(s => string.IsNullOrEmpty(filterStatus) ||
                    s.Status.ToString() == filterStatus)
        ?? Enumerable.Empty<ShipmentDto>();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private void ShowCreateForm()
    {
        newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(7) };
        showCreateForm = true;
    }

    private async Task CreateShipment()
    {
        var request = new CreateShipmentRequest(
            null,
            newShipment.Origin,
            newShipment.Destination,
            newShipment.EstimatedDelivery,
            newShipment.CustomerEmail,
            newShipment.Description);

        await ShipmentService.CreateShipmentAsync(request);
        showCreateForm = false;
        await LoadShipments();
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };

    private class NewShipmentModel
    {
        public string Origin { get; set; } = "";
        public string Destination { get; set; } = "";
        public string CustomerEmail { get; set; } = "";
        public string Description { get; set; } = "";
        public DateTime EstimatedDelivery { get; set; } = DateTime.UtcNow.AddDays(7);
    }
}

